// One direct-global output per thread; warp lanes traverse contiguous x values.
__global__ void derivative_y_direct(const float *f, float *df)
{
  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  const int j = blockIdx.y * blockDim.y + threadIdx.y;
  const int k = blockIdx.z;
  const int plane = k * mx * my;

  // Match the baseline's period-(my-1) halo mapping independently for each offset.
  int jm1 = j - 1; if (jm1 < 0) jm1 += my - 1;
  int jp1 = j + 1; if (jp1 >= my) jp1 -= my - 1;
  int jm2 = j - 2; if (jm2 < 0) jm2 += my - 1;
  int jp2 = j + 2; if (jp2 >= my) jp2 -= my - 1;
  int jm3 = j - 3; if (jm3 < 0) jm3 += my - 1;
  int jp3 = j + 3; if (jp3 >= my) jp3 -= my - 1;
  int jm4 = j - 4; if (jm4 < 0) jm4 += my - 1;
  int jp4 = j + 4; if (jp4 >= my) jp4 -= my - 1;

  const float fm1 = f[plane + jm1 * mx + i];
  const float fp1 = f[plane + jp1 * mx + i];
  const float fm2 = f[plane + jm2 * mx + i];
  const float fp2 = f[plane + jp2 * mx + i];
  const float fm3 = f[plane + jm3 * mx + i];
  const float fp3 = f[plane + jp3 * mx + i];
  const float fm4 = f[plane + jm4 * mx + i];
  const float fp4 = f[plane + jp4 * mx + i];

  df[plane + j * mx + i] =
    ( c_ay * ( fp1 - fm1 )
    + c_by * ( fp2 - fm2 )
    + c_cy * ( fp3 - fm3 )
    + c_dy * ( fp4 - fm4 ) );
}

