__global__ void derivative_y(float *f, float *df)
{
  __shared__ float s_f[yTileRows + 8][sPencils];

  const int tx = static_cast<int>(threadIdx.x);
  const int ty = static_cast<int>(threadIdx.y);
  const int i = static_cast<int>(blockIdx.x) * static_cast<int>(blockDim.x) + tx;
  const int tileY = static_cast<int>(blockIdx.y) * yTileRows;
  const int j = tileY + ty;
  const int k = static_cast<int>(blockIdx.z);
  const int sj = ty + 4;
  const int planeOffset = k * mx * my;
  const int globalIdx = planeOffset + j * mx + i;

  s_f[sj][tx] = f[globalIdx];

  if (ty < 4) {
    int haloY = tileY + ty - 4;
    if (haloY < 0)
      haloY += my - 1;
    s_f[ty][tx] = f[planeOffset + haloY * mx + i];
  }

  if (ty >= yTileRows - 4) {
    int haloY = tileY + ty + 4;
    if (haloY >= my)
      haloY -= my - 1;
    s_f[ty + 8][tx] = f[planeOffset + haloY * mx + i];
  }

  __syncthreads();

  df[globalIdx] =
    ( c_ay * ( s_f[sj+1][tx] - s_f[sj-1][tx] )
    + c_by * ( s_f[sj+2][tx] - s_f[sj-2][tx] )
    + c_cy * ( s_f[sj+3][tx] - s_f[sj-3][tx] )
    + c_dy * ( s_f[sj+4][tx] - s_f[sj-4][tx] ) );
}

