// Direct-global y stencil with one output per thread. The 64x4 block keeps
// warp lanes contiguous in x while covering four complete y rows per block.
__global__ void derivative_y(const float *f, float *df)
{
  const int i = threadIdx.x;
  const int j = blockIdx.y * blockDim.y + threadIdx.y;
  const int k = blockIdx.z;
  const int planeOffset = k * mx * my + i;
  const int globalIdx = planeOffset + j * mx;

  int jm1 = j - 1;
  int jp1 = j + 1;
  int jm2 = j - 2;
  int jp2 = j + 2;
  int jm3 = j - 3;
  int jp3 = j + 3;
  int jm4 = j - 4;
  int jp4 = j + 4;

  // Match the baseline halo convention: values outside [0, my-1] wrap
  // by my-1, leaving the endpoint row itself in the interval.
  if (jm1 < 0) jm1 += my - 1;
  if (jp1 >= my) jp1 -= my - 1;
  if (jm2 < 0) jm2 += my - 1;
  if (jp2 >= my) jp2 -= my - 1;
  if (jm3 < 0) jm3 += my - 1;
  if (jp3 >= my) jp3 -= my - 1;
  if (jm4 < 0) jm4 += my - 1;
  if (jp4 >= my) jp4 -= my - 1;

  df[globalIdx] =
    ( c_ay * ( f[planeOffset + jp1 * mx] - f[planeOffset + jm1 * mx] )
    + c_by * ( f[planeOffset + jp2 * mx] - f[planeOffset + jm2 * mx] )
    + c_cy * ( f[planeOffset + jp3 * mx] - f[planeOffset + jm3 * mx] )
    + c_dy * ( f[planeOffset + jp4 * mx] - f[planeOffset + jm4 * mx] ) );
}

extern "C" void run(const float *A, const float *B, float *C, float *scratch,
                    int n, int m, int k, float alpha, float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }

  derivative_y<<<dim3(1, my / 4, mz), dim3(mx, 4, 1)>>>(A, C);
}

