// Preserve the baseline's y halo mapping: negative rows wrap by my-1,
// while rows at or above my wrap back by my-1; row my-1 remains distinct.
__device__ __forceinline__ int baseline_y_index(int row)
{
  if (row < 0) return row + (my - 1);
  if (row >= my) return row - (my - 1);
  return row;
}

// Each warp covers contiguous x values. Each thread computes two adjacent
// y outputs from their shared ten-row input neighborhood held in registers.
__global__ void derivative_y(const float *f, float *df)
{
  const int x = blockIdx.x * blockDim.x + threadIdx.x;
  const int y0 = blockIdx.y * (blockDim.y * 2) + threadIdx.y * 2;
  const int k = blockIdx.z;
  if (x >= mx || y0 >= my) return;

  const int planeBase = k * mx * my + x;

  const int r0 = baseline_y_index(y0 - 4);
  const int r1 = baseline_y_index(y0 - 3);
  const int r2 = baseline_y_index(y0 - 2);
  const int r3 = baseline_y_index(y0 - 1);
  const int r4 = baseline_y_index(y0);
  const int r5 = baseline_y_index(y0 + 1);
  const int r6 = baseline_y_index(y0 + 2);
  const int r7 = baseline_y_index(y0 + 3);
  const int r8 = baseline_y_index(y0 + 4);
  const int r9 = baseline_y_index(y0 + 5);

  const float v0 = f[planeBase + r0 * mx];
  const float v1 = f[planeBase + r1 * mx];
  const float v2 = f[planeBase + r2 * mx];
  const float v3 = f[planeBase + r3 * mx];
  const float v4 = f[planeBase + r4 * mx];
  const float v5 = f[planeBase + r5 * mx];
  const float v6 = f[planeBase + r6 * mx];
  const float v7 = f[planeBase + r7 * mx];
  const float v8 = f[planeBase + r8 * mx];
  const float v9 = f[planeBase + r9 * mx];

  const float d0 =
    ( c_ay * (v5 - v3)
    + c_by * (v6 - v2)
    + c_cy * (v7 - v1)
    + c_dy * (v8 - v0) );
  const float d1 =
    ( c_ay * (v6 - v4)
    + c_by * (v7 - v3)
    + c_cy * (v8 - v2)
    + c_dy * (v9 - v1) );

  const int outputBase = planeBase + y0 * mx;
  df[outputBase] = d0;
  if (y0 + 1 < my)
    df[outputBase + mx] = d1;
}

// Two y outputs per thread; four y-thread rows per block retain an 8-row
// output span while each warp continues to span adjacent x elements.
extern "C" void run(const float*A,const float*B,float*C,float*scratch,int n,int m,int k,float alpha,float beta)
{
  static bool initialized = false;
  if (!initialized) {
    setDerivativeParameters();
    initialized = true;
  }

  dim3 launchBlock(32, 4, 1);
  dim3 launchGrid((mx + launchBlock.x - 1) / launchBlock.x,
                  (my + launchBlock.y * 2 - 1) / (launchBlock.y * 2),
                  mz);
  derivative_y<<<launchGrid, launchBlock>>>(A, C);
}

