// Map y halo coordinates with the baseline period-(my-1) endpoint convention.
__device__ __forceinline__ int wrapY(int y)
{
  const int period = my - 1;
  int mapped = y % period;
  return mapped < 0 ? mapped + period : mapped;
}

__global__ void derivative_y(float *f, float *df)
{
  __shared__ float s_f[yTileRows + 8][sPencils];

  const int i = blockIdx.x * blockDim.x + threadIdx.x;
  const int tileStart = blockIdx.y * yTileRows;
  const int j = tileStart + threadIdx.y;
  const int k = blockIdx.z;
  const int si = threadIdx.x;
  const int sj = threadIdx.y + 4;
  const int globalIdx = k * mx * my + j * mx + i;

  if (j < my) {
    s_f[sj][si] = f[globalIdx];
  } else {
    s_f[sj][si] = 0.0f;
  }

  // Load the four-row halos directly. The period-(my-1) mapping preserves
  // the baseline's duplicated-endpoint convention, including y=63.
  if (threadIdx.y < 4) {
    const int lowerY = wrapY(tileStart + threadIdx.y - 4);
    const int upperY = wrapY(tileStart + yTileRows + threadIdx.y);
    s_f[threadIdx.y][si] = f[k * mx * my + lowerY * mx + i];
    s_f[threadIdx.y + yTileRows + 4][si] =
        f[k * mx * my + upperY * mx + i];
  }

  __syncthreads();

  if (j < my) {
    df[globalIdx] =
      ( c_ay * ( s_f[sj+1][si] - s_f[sj-1][si] )
      + c_by * ( s_f[sj+2][si] - s_f[sj-2][si] )
      + c_cy * ( s_f[sj+3][si] - s_f[sj-3][si] )
      + c_dy * ( s_f[sj+4][si] - s_f[sj-4][si] ) );
  }
}

// y derivative using x-wide blocks and 16 output rows per shared-memory tile.
#include <cuda_runtime.h>
