  const int total = mx * my * mz;
  if (idx >= total) return;

  const int y = (idx / mx) % my;
  const int rowBase = idx - y * mx;

  // Match the original shared-tile halo: only indices outside [0, my-1]
  // wrap, and the wrap period is my-1 (the endpoint row is retained).
  int ym1 = y - 1;
  int ym2 = y - 2;
  int ym3 = y - 3;
  int ym4 = y - 4;
  int yp1 = y + 1;
  int yp2 = y + 2;
  int yp3 = y + 3;
  int yp4 = y + 4;
  if (ym1 < 0) ym1 += my - 1;
  if (ym2 < 0) ym2 += my - 1;
  if (ym3 < 0) ym3 += my - 1;
  if (ym4 < 0) ym4 += my - 1;
  if (yp1 >= my) yp1 -= my - 1;
  if (yp2 >= my) yp2 -= my - 1;
  if (yp3 >= my) yp3 -= my - 1;
  if (yp4 >= my) yp4 -= my - 1;

  df[idx] =
    ( c_ay * (f[rowBase + yp1 * mx] - f[rowBase + ym1 * mx])
    + c_by * (f[rowBase + yp2 * mx] - f[rowBase + ym2 * mx])
    + c_cy * (f[rowBase + yp3 * mx] - f[rowBase + ym3 * mx])
    + c_dy * (f[rowBase + yp4 * mx] - f[rowBase + ym4 * mx]) );
}

